from collections import deque

def fill_enclosed_regions(grid, wall_color, fill_color):
    """
    Fill all enclosed regions (3s that cannot reach the border) with fill_color.
    """
    if len(grid) == 0 or len(grid[0]) == 0:
        return grid

    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]

    # Flood fill from all border pixels that are not wall_color
    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if (r == 0 or r == rows-1 or c == 0 or c == cols-1):
                if grid[r][c] != wall_color:
                    visited[r][c] = True
                    queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] != wall_color:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    # Now mark all unvisited non-wall pixels as enclosed
    result = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] != wall_color:
                result[r][c] = wall_color  # or fill_color

    return result

